mapper.update:
UPDATE article_comments
SET root_id = #{rootId},
    updated_at = NOW()
WHERE id = #{id}
  AND article_id = #{articleId}

UPDATE article_comments
SET reply_count = GREATEST(reply_count - 1, 0),
    updated_at = NOW()
WHERE id = #{id}
  AND article_id = #{articleId}

UPDATE article_comment_likes
SET deleted = 0,
    updated_at = NOW()
WHERE comment_id = #{commentId}
  AND article_id = #{articleId}
  AND user_id = #{userId}
  AND deleted = 1

UPDATE article_comment_likes
SET deleted = 1,
    updated_at = NOW()
WHERE comment_id = #{commentId}
  AND article_id = #{articleId}
  AND user_id = #{userId}
  AND deleted = 0

UPDATE article_comments
SET like_count = GREATEST(like_count - 1, 0),
    updated_at = NOW()
WHERE id = #{id}
  AND article_id = #{articleId}

